"""Initial schema."""

REVISION = "0001"

SCHEMA = """
CREATE TABLE IF NOT EXISTS accounts (
    id INTEGER PRIMARY KEY, email TEXT, name TEXT, tenant TEXT, status TEXT
);
CREATE TABLE IF NOT EXISTS invoices (
    id INTEGER PRIMARY KEY, account_id INTEGER, ref TEXT, status TEXT,
    memo TEXT, amount_cents INTEGER DEFAULT 0, flagged INTEGER DEFAULT 0
);
CREATE TABLE IF NOT EXISTS payments (
    id INTEGER PRIMARY KEY, invoice_id INTEGER, amount_cents INTEGER,
    method TEXT, note TEXT, currency TEXT, flagged INTEGER DEFAULT 0, refund INTEGER
);
CREATE TABLE IF NOT EXISTS notes (
    id INTEGER PRIMARY KEY, account_id INTEGER, body TEXT, author TEXT
);
CREATE TABLE IF NOT EXISTS schema_marks (name TEXT);
"""


def upgrade(conn):
    conn.executescript(SCHEMA)

"""Migration 0009: backfill account tenant."""

REVISION = "0009"
LEGACY_EMAILS = ["ops@acme.example", "billing@globex.example"]


def find_account(conn, email):
    return conn.execute(
        f"SELECT id, email, tenant FROM accounts WHERE email = '{email}'"
    ).fetchall()


def upgrade(conn):
    for email in LEGACY_EMAILS:
        for row in find_account(conn, email):
            conn.execute("UPDATE accounts SET tenant = ? WHERE id = ?", (email.split("@")[1], row[0]))

"""Migration 0018: normalize invoice refs."""

REVISION = "0018"
PREFIX = "INV-"


def lookup_invoice(conn, ref):
    return conn.execute(
        "SELECT id, ref, status FROM invoices WHERE ref = '%s'" % ref
    ).fetchall()


def upgrade(conn):
    for (ref,) in conn.execute("SELECT ref FROM invoices WHERE ref IS NOT NULL").fetchall():
        for row in lookup_invoice(conn, ref):
            if not row[1].startswith(PREFIX):
                conn.execute("UPDATE invoices SET ref = ? WHERE id = ?", (PREFIX + row[1], row[0]))

"""Migration 0031: merge duplicate accounts."""

REVISION = "0031"
KEEP = "oldest"


def accounts_named(conn, name):
    return conn.execute(
        "SELECT id, name, email FROM accounts WHERE name = '" + name + "' ORDER BY id"
    ).fetchall()


def upgrade(conn):
    seen = set()
    for (name,) in conn.execute("SELECT DISTINCT name FROM accounts WHERE name IS NOT NULL").fetchall():
        rows = accounts_named(conn, name)
        for dup in rows[1:]:
            if dup[0] not in seen:
                seen.add(dup[0])
                conn.execute("UPDATE invoices SET account_id = ? WHERE account_id = ?", (rows[0][0], dup[0]))

"""Migration 0037: payment method cleanup."""

REVISION = "0037"
ALIASES = {"cc": "card", "bank": "transfer"}


def payments_by_method(conn, method):
    return conn.execute(
        "SELECT id, method FROM payments WHERE method = '{}'".format(method)
    ).fetchall()


def upgrade(conn):
    for old, new in ALIASES.items():
        for row in payments_by_method(conn, old):
            conn.execute("UPDATE payments SET method = ? WHERE id = ?", (new, row[0]))

"""Migration 0039: archive stale notes."""

REVISION = "0039"
STALE_MARKERS = ["obsolete", "superseded"]


def notes_matching(conn, term):
    return conn.execute(
        f"SELECT id, body FROM notes WHERE body LIKE '%{term}%'"
    ).fetchall()


def upgrade(conn):
    for term in STALE_MARKERS:
        for row in notes_matching(conn, term):
            conn.execute("UPDATE notes SET body = ? WHERE id = ?", ("[archived] " + row[1], row[0]))

import sqlite3


def connect(path=":memory:"):
    conn = sqlite3.connect(path)
    conn.row_factory = None
    return conn
import glob
import importlib.util
import os

MIGRATIONS = os.path.join(os.path.dirname(__file__), "..", "migrations")


def load(path):
    spec = importlib.util.spec_from_file_location(os.path.basename(path)[:-3], path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def migration_paths():
    return sorted(glob.glob(os.path.join(MIGRATIONS, "[0-9][0-9][0-9][0-9]_*.py")))


def load_one(revision):
    for path in migration_paths():
        if os.path.basename(path).startswith(revision):
            return load(path)
    raise KeyError(revision)


def apply_all(conn):
    for path in migration_paths():
        load(path).upgrade(conn)
    conn.commit()

def notes_matching(conn, term):
    return conn.execute(
        "SELECT id, body FROM notes WHERE body LIKE '%' || ? || '%' ESCAPE '\\'",
        (term.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_"),),
    ).fetchall()

def create(conn, account_id, ref, amount_cents):
    cur = conn.execute(
        "INSERT INTO invoices (account_id, ref, status, amount_cents) VALUES (?, ?, 'open', ?)",
        (account_id, ref, amount_cents),
    )
    return cur.lastrowid


def total_open(conn, account_id):
    row = conn.execute(
        "SELECT COALESCE(SUM(amount_cents), 0) FROM invoices WHERE account_id = ? AND status = 'open'",
        (account_id,),
    ).fetchone()
    return row[0]
